import { Column } from '@tanstack/react-table';
/**
 * Determines whether a column sits at a top-level group boundary.
 *
 * A column is at a group boundary when its rightmost leaf column is the same as
 * the rightmost leaf of its root-level ancestor.  This means the column (or the
 * group it belongs to) terminates a top-level column group, which is where a
 * vertical separator should appear when `cellBordersStyle` is `'group'`.
 *
 * Standalone (ungrouped) columns are always considered a group boundary.
 */
export declare const isGroupBoundaryColumn: <TData>(column: Column<TData, unknown>) => boolean;
